import{_ as t,o as e,c as s,a5 as n}from"./chunks/framework.CXroN2RO.js";const m=JSON.parse('{"title":"ヘッダー分割と Assembly Definition","description":"","frontmatter":{"title":"ヘッダー分割と Assembly Definition","study":{"source":"C++ Wiki","kind":"本文","status":"既存原稿","summary":"C++のヘッダー/ライブラリ分割とUnityのAssembly Definition(.asmdef)は、仕組みは全く別物ですが、目的は同じです: 「コードの依存関係を物理的に構造化し、ビルド時間と設計秩序を守る」。C#で.asmdefを整理した経験は、C++のモジュール分割設計にそのまま活きます。"}},"headers":[],"relativePath":"languages/csharp/headers-vs-asmdef.md","filePath":"languages/csharp/headers-vs-asmdef.md"}'),i={name:"languages/csharp/headers-vs-asmdef.md"};function d(l,a,r,o,h,p){return e(),s("div",null,[...a[0]||(a[0]=[n(`<h1 id="ヘッダー分割と-assembly-definition" tabindex="-1">ヘッダー分割と Assembly Definition <a class="header-anchor" href="#ヘッダー分割と-assembly-definition" aria-label="Permalink to &quot;ヘッダー分割と Assembly Definition&quot;">​</a></h1><h2 id="一言で言うと" tabindex="-1">一言で言うと <a class="header-anchor" href="#一言で言うと" aria-label="Permalink to &quot;一言で言うと&quot;">​</a></h2><p>C++のヘッダー/ライブラリ分割とUnityのAssembly Definition(.asmdef)は、<strong>仕組みは全く別物</strong>ですが、<strong>目的は同じ</strong>です: 「コードの依存関係を物理的に構造化し、ビルド時間と設計秩序を守る」。C#で.asmdefを整理した経験は、C++のモジュール分割設計にそのまま活きます。</p><h2 id="対応表" tabindex="-1">対応表 <a class="header-anchor" href="#対応表" aria-label="Permalink to &quot;対応表&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Unity (.asmdef)</th><th>C++</th><th>対応の質</th></tr></thead><tbody><tr><td>.asmdefファイルでアセンブリ分割</td><td>ライブラリ分割(add_library → <a href="/study/tools/build/build-tools-cmake.html">CMake</a>)</td><td>目的同一</td></tr><tr><td>Assembly Definition References(参照宣言)</td><td>target_link_libraries(依存宣言)</td><td>目的同一</td></tr><tr><td>参照がないと型が見えない</td><td>includeパス+リンクがないと使えない</td><td>C++は2段階(宣言と実体)</td></tr><tr><td>internal(アセンブリ内公開)</td><td>無名namespace(翻訳単位内)/ 非公開ヘッダー(ライブラリ内)</td><td><strong>C++に完全対応物なし</strong></td></tr><tr><td>循環参照はエラー</td><td>循環リンクは(静的ライブラリでは)通ってしまうことがある</td><td>C++の方が緩い=自衛が必要</td></tr><tr><td>asmdef分割でスクリプトコンパイル高速化</td><td>ヘッダー衛生・分割でビルド高速化(<a href="/study/tools/build/build-speed.html">第8部</a>)</td><td>目的同一</td></tr></tbody></table><h2 id="決定的な違い-「宣言の配布」という仕事の有無" tabindex="-1">決定的な違い: 「宣言の配布」という仕事の有無 <a class="header-anchor" href="#決定的な違い-「宣言の配布」という仕事の有無" aria-label="Permalink to &quot;決定的な違い: 「宣言の配布」という仕事の有無&quot;">​</a></h2><ul><li>C#: アセンブリ参照を張れば、<strong>メタデータから型情報が自動で見える</strong>。公開範囲はpublic/internalで制御</li><li>C++: 型を見せるには<strong>ヘッダーを配る</strong>という物理的な作業が要る(→ <a href="/study/runtime/cpp-internals/translation-units-and-headers.html">翻訳単位</a>)。そして「見せる範囲」はヘッダーの置き場所で設計する:</li></ul><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>mylib/</span></span>
<span class="line"><span>├── include/mylib/     ← 公開ヘッダー(利用者が見てよいもの)= C#のpublic相当</span></span>
<span class="line"><span>│   └── enemy.h</span></span>
<span class="line"><span>└── src/               ← 非公開ヘッダー+実装 = internal相当</span></span>
<span class="line"><span>    ├── enemy_internal.h</span></span>
<span class="line"><span>    └── enemy.cpp</span></span></code></pre></div><p>CMakeでは <code>target_include_directories(mylib PUBLIC include PRIVATE src)</code> がこの公開範囲の宣言になります。**「公開APIの設計=公開ヘッダーの設計」**がC++流です。</p><h2 id="依存方向の強制force" tabindex="-1">依存方向の強制force <a class="header-anchor" href="#依存方向の強制force" aria-label="Permalink to &quot;依存方向の強制force&quot;">​</a></h2><p>.asmdefで「UIはCoreを参照するが、CoreはUIを参照できない」を強制した経験があるはずです。C++でも同じことをライブラリ分割+リンク宣言で行います(→ <a href="/study/design/foundations/dependency.html">依存の方向</a>)。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>game_core(ゲームルール)← game_ui(表示)← game_app(組み立て)</span></span>
<span class="line"><span>CMakeで core が ui にリンクしていたら設計違反 — レビューで機械的に検出できる</span></span></code></pre></div><ul><li>C++で注意: <strong>includeだけなら循環がコンパイルできてしまう</strong>場合がある(ヘッダーオンリー同士)。「参照を張らなければ物理的に見えない」.asmdefより自衛が必要</li><li>C++20モジュール(<code>import</code>)はこの状況をC#に近づける新機構だが、ツールチェーンの普及待ち(→ <a href="/study/runtime/cpp-internals/translation-units-and-headers.html">翻訳単位</a>)</li></ul><h2 id="ビルド時間の観点" tabindex="-1">ビルド時間の観点 <a class="header-anchor" href="#ビルド時間の観点" aria-label="Permalink to &quot;ビルド時間の観点&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Unityの経験則</th><th>C++での対応</th></tr></thead><tbody><tr><td>巨大な単一Assembly-CSharp.dllは変更のたび全コンパイル</td><td>「何でも入りヘッダー」が全再コンパイルを誘発</td></tr><tr><td>よく変わるゲームコードと安定した基盤を別asmdefに</td><td>変更頻度でヘッダー・ライブラリを層別(<a href="/study/tools/build/build-speed.html">第8部</a>)</td></tr><tr><td>Editor専用asmdefで本体から分離</td><td>ツール・エディタコードの別ターゲット化</td></tr></tbody></table><p>**「変更頻度の高いものに、多くのものを依存させない」**という原則は両者共通で、Unityでの整理経験がそのまま通用します。</p><h2 id="unity開発者が誤解しやすい点" tabindex="-1">Unity開発者が誤解しやすい点 <a class="header-anchor" href="#unity開発者が誤解しやすい点" aria-label="Permalink to &quot;Unity開発者が誤解しやすい点&quot;">​</a></h2><ol><li>「フォルダを分ければ分離される」— C++ではフォルダに意味はない。<strong>ヘッダーの公開範囲とリンク宣言</strong>が分離の実体</li><li>「internalがないから全公開しかない」— 非公開ヘッダー・無名namespace・pimplで実質的な内部化は可能(粒度は粗いが)</li><li>.asmdefを切りすぎて管理が地獄になった経験があるなら、C++のライブラリ分割も同じ罠がある——<strong>分割は依存の境界に沿って最小限</strong>が両言語共通の答え</li></ol><h2 id="理解度チェック" tabindex="-1">理解度チェック <a class="header-anchor" href="#理解度チェック" aria-label="Permalink to &quot;理解度チェック&quot;">​</a></h2><ol><li>.asmdefの参照宣言に対応するC++の仕組みは何ですか(2段階)。</li><li>C#のinternalに完全対応するC++機能がない中で、近い効果を得る手段を2つ挙げてください。</li><li>「公開APIの設計=公開ヘッダーの設計」とはどういうことですか。</li></ol><h2 id="演習" tabindex="-1">演習 <a class="header-anchor" href="#演習" aria-label="Permalink to &quot;演習&quot;">​</a></h2><p><a href="/study/tools/build/samples/cmake-demo.html">samples/cmake_demo/</a> の game_core を「公開ヘッダー(include/)と実装(src/)」構成に整理し、mainから非公開ヘッダーをincludeしようとするとパスが通らないことを確認してください。</p><hr><p>前: <a href="/study/languages/csharp/delegates-events-function-pointers.html">関数ポインタとdelegate</a> | <a href="/study/languages/csharp/">カテゴリ目次</a> | 次: <a href="/study/languages/csharp/il2cpp.html">ネイティブビルドとIL2CPP</a></p>`,24)])])}const u=t(i,[["render",d]]);export{m as __pageData,u as default};
